"use client";
import { useEffect, useLayoutEffect, useRef, useState } from "react";
import "./word-rotator.css";

/** Cycles through words in place. The line eases to each word's width, so the sentence never jumps. */
export function WordRotator({
  words,
  interval = 2400,
  className = "",
}: {
  words: string[];
  interval?: number;
  className?: string;
}) {
  const [index, setIndex] = useState(0);
  const [width, setWidth] = useState<number | undefined>(undefined);
  const measure = useRef<HTMLSpanElement>(null);
  const root = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    if (words.length < 2 || matchMedia("(prefers-reduced-motion:reduce)").matches) return;
    let timer = 0;
    // Only cycle while on screen.
    const observer = new IntersectionObserver(([entry]) => {
      clearInterval(timer);
      if (entry.isIntersecting) timer = window.setInterval(() => setIndex((i) => (i + 1) % words.length), interval);
    });
    observer.observe(root.current!);
    return () => {
      observer.disconnect();
      clearInterval(timer);
    };
  }, [words.length, interval]);
  useLayoutEffect(() => {
    const el = measure.current?.children[index] as HTMLElement | undefined;
    if (el) setWidth(el.getBoundingClientRect().width);
  }, [index, words]);
  return (
    <span ref={root} className={`forme-rotator ${className}`}>
      <span className="forme-rotator-sr">{words.join(", ")}</span>
      <span className="forme-rotator-window" aria-hidden="true" style={{ width }}>
        <span key={index} className="forme-rotator-word">
          {words[index]}
        </span>
      </span>
      {/* Hidden copies measure each word in the surrounding font. */}
      <span ref={measure} className="forme-rotator-measure" aria-hidden="true">
        {words.map((w) => (
          <span key={w}>{w}</span>
        ))}
      </span>
    </span>
  );
}

.forme-rotator {
  position: relative;
  display: inline-block;
  vertical-align: bottom;
}
.forme-rotator-window {
  display: inline-block;
  overflow: hidden;
  /* Room for descenders and the slide. */
  padding-bottom: 0.12em;
  margin-bottom: -0.12em;
  vertical-align: bottom;
  white-space: nowrap;
  transition: width 0.5s cubic-bezier(0.3, 1.1, 0.4, 1);
}
.forme-rotator-word {
  display: inline-block;
  animation: forme-rotator-in 0.55s cubic-bezier(0.2, 0.9, 0.2, 1);
}
@keyframes forme-rotator-in {
  from {
    opacity: 0;
    filter: blur(8px);
    transform: translateY(60%);
  }
}
.forme-rotator-measure {
  position: absolute;
  top: 0;
  left: 0;
  visibility: hidden;
  white-space: nowrap;
  pointer-events: none;
}
.forme-rotator-measure > span {
  position: absolute;
}
.forme-rotator-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
@media (prefers-reduced-motion: reduce) {
  .forme-rotator-window {
    transition: none;
  }
  .forme-rotator-word {
    animation: none;
  }
}
